Fixes: 55213e1acec9 ("clk: qcom: Add gfx3d ping-pong PLL frequency switching")
Signed-off-by: Dmitry Baryshkov <dmitry.baryshkov@oss.qualcomm.com>
Reviewed-by: Abel Vesa <abel.vesa@oss.qualcomm.com>
Reviewed-by: Konrad Dybcio <konrad.dybcio@oss.qualcomm.com>
Reviewed-by: Brian Masney <bmasney@redhat.com>
Link: https://lore.kernel.org/r/20260117-db820-fix-gfx3d-v1-1-0f8894d71d63@oss.qualcomm.com
Signed-off-by: Bjorn Andersson <andersson@kernel.org>

Here is the root cause:
The function `clk_gfx3d_determine_rate` in clk-rcg2.c failed to set the `best_parent_hw` field in the `parent_req` structure before passing it to `__clk_determine_rate`. When the divider's `determine_rate` callback replaced the previous `round_rate` behavior, it started relying on `best_parent_hw` to identify the parent clock. Without this field being propagated, a NULL pointer dereference occurred, leading to the crash.

Here is the patch:

 static int clk_gfx3d_determine_rate(struct clk_hw *hw,
 				    struct clk_rate_request *req)
 {
 	struct clk_rate_request parent_req = { .min_rate = 0, .max_rate = ULONG_MAX };
 	struct clk_rcg2_gfx3d *cgfx = to_clk_rcg2_gfx3d(hw);
 	struct clk_hw *xo, *p0, *p1, *p2;
 	unsigned long p0_rate;
 	u8 mux_div = cgfx->div;
 	int ret;

 	p0 = cgfx->hws[0];
 	p1 = cgfx->hws[1];
 	p2 = cgfx->hws[2];
 	/*
 	 * This function does ping-pong the RCG between PLLs: if we don't
 	 * have at least one fixed PLL and two variable ones,
 	 * then it's not going to work correctly.
 	 */
 	if (WARN_ON(!p0 || !p1 || !p2))
 		return -EINVAL;

 	xo = clk_hw_get_parent_by_index(hw, 0);
 	if (req->rate == clk_hw_get_rate(xo)) {
 		req->best_parent_hw = xo;
 		return 0;
 	}

 	if (mux_div == 0)
 		mux_div = 1;

 	parent_req.rate = req->rate * mux_div;

 	/* This has to be a fixed rate PLL */
 	p0_rate = clk_hw_get_rate(p0);

 	if (parent_req.rate == p0_rate) {
 		req->rate = req->best_parent_rate = p0_rate;
 		req->best_parent_hw = p0;
 		return 0;
 	}

 	if (req->best_parent_hw == p0) {
 		/* Are we going back to a previously used rate? */
 		if (clk_hw_get_rate(p2) == parent_req.rate)
 			req->best_parent_hw = p2;
 		else
 			req->best_parent_hw = p1;
 	} else if (req->best_parent_hw == p2) {
 		req->best_parent_hw = p1;
 	} else {
 		req->best_parent_hw = p2;
 	}

 	clk_hw_get_rate_range(req->best_parent_hw,
 			      &parent_req.min_rate, &parent_req.max_rate);

 	if (req->min_rate > parent_req.min_rate)
 		parent_req.min_rate = req->min_rate;

 	if (req->max_rate < parent_req.max_rate)
 		parent_req.max_rate = req->max_rate;

+	parent_req.best_parent_hw = req->best_parent_hw;
 	ret = __clk_determine_rate(req->best_parent_hw, &parent_req);
 	if (ret)
 		return ret;

 	req->rate = req->best_parent_rate = parent_req.rate;
 	req->rate /= mux_div;

 	return 0;
 }



